"""Pure per-line arithmetic; evidence, exception authority and eligibility are external.

Amounts use Decimal throughout and each converted line is rounded half-up once.
An unresolved calculation returns ``allowed_cents=None``, never an invented zero.
Informational findings have ``blocking=False``; original cap findings survive a
caller-validated replacement. A replacement does not resolve an undefined cap
in this component: that would need an explicit additional source rule.
"""

from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
import re


KNOWN_CATEGORIES = frozenset({"transport", "conference", "lodging", "meals", "personal"})


def _decimal(value):
    if isinstance(value, bool) or value is None:
        raise ValueError("Expected a finite decimal number")
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError) as error:
        raise ValueError("Expected a finite decimal number") from error
    if not number.is_finite():
        raise ValueError("Expected a finite decimal number")
    return number


def _day(value):
    if type(value) is date:
        return value
    if not isinstance(value, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        raise ValueError("Expected a local YYYY-MM-DD date")
    return date.fromisoformat(value)


def _text(value):
    text = format(value, "f")
    return (text.rstrip("0").rstrip(".") if "." in text else text) if value else "0"


def _precision(*values):
    return max(50, sum(len(v.as_tuple().digits) + abs(v.as_tuple().exponent) for v in values) + 10)


def calculate_line(*, gross, currency, category, units, destination, payment_date,
                   fx_rows, caps_rows, replacement_allowed=None):
    """Calculate one supported line using native table headings and ``_ref``.

    The caller must establish paid evidence and validate any Finance replacement's
    actor, claim/revision, cost and scope. This function grants no eligibility
    waiver, approval, request authority or closure. ``allowed_original`` remains
    available when only FX is unresolved; ``rate=None`` on a foreign personal
    purchase means conversion is unnecessary because its known entitlement is 0.
    """
    result = dict(allowed_cents=None, allowed_original=None, rate=None,
                  findings=[], source_refs=[])

    def finding(code, detail, *, blocking=True, **facts):
        result["findings"].append(dict(code=code, detail=detail, blocking=blocking, **facts))

    def refs(rows, complete=None):
        for row in rows:
            reference = row.get("_ref")
            if reference and reference not in result["source_refs"]:
                result["source_refs"].append(reference)
        if complete and complete not in result["source_refs"]:
            result["source_refs"].append(complete)

    try:
        gross_amount, unit_count = _decimal(gross), _decimal(units)
        paid_on = _day(payment_date)
        if gross_amount < 0 or unit_count <= 0 or unit_count != unit_count.to_integral_value():
            raise ValueError("Gross must be nonnegative and units a positive integer")
        if not isinstance(currency, str) or not re.fullmatch(r"[A-Z]{3}", currency):
            raise ValueError("Currency must be an explicit three-letter code")
        replacement = None if replacement_allowed is None else _decimal(replacement_allowed)
        if replacement is not None and replacement < 0:
            raise ValueError("Replacement allowed amount must be nonnegative")
    except ValueError as error:
        finding("invalid_input", str(error))
        return result

    if category not in KNOWN_CATEGORIES:
        finding("unknown_category", "No supplied arithmetic rule for category: " + str(category))
        return result
    if category == "personal":
        result.update(allowed_cents=0, allowed_original="0", rate="1" if currency == "EUR" else None)
        finding("personal_excluded", "Personal purchases have known zero entitlement", blocking=False)
        return result

    ordinary_allowed = gross_amount
    if category in {"lodging", "meals"}:
        candidates = [row for row in caps_rows if row.get("Destination") == destination
                      and row.get("Category") == category and row.get("Currency") == currency]
        matching = []
        for row in candidates:
            try:
                start, end = _day(row.get("Effective from")), _day(row.get("Effective to"))
                if end < start:
                    raise ValueError("Cap effective period ends before it starts")
            except ValueError as error:
                refs([row])
                finding("invalid_cap", str(error))
                return result
            if start <= paid_on <= end:
                matching.append(row)
        refs(matching)
        if len(matching) != 1:
            refs(candidates, "REGISTERS-CAPS:complete-tab")
            finding("missing_cap" if not matching else "ambiguous_cap",
                    "Need exactly one applicable destination/category/currency/payment-date cap")
            return result
        try:
            cap = _decimal(matching[0].get("Amount per unit"))
            if cap < 0:
                raise ValueError("Cap cannot be negative")
        except ValueError as error:
            finding("invalid_cap", str(error))
            return result
        with localcontext() as context:
            context.prec = _precision(gross_amount, cap, unit_count)
            limit = cap * unit_count
            ordinary_allowed = min(gross_amount, limit)
        if ordinary_allowed < gross_amount:
            finding("cap_applied", "Ordinary allowed amount is limited by the applicable cap and units",
                    blocking=False, gross_original=_text(gross_amount), cap_total_original=_text(limit),
                    ordinary_allowed_original=_text(ordinary_allowed))

    allowed = ordinary_allowed if replacement is None else replacement
    if replacement is not None:
        finding("replacement_applied", "Caller-validated replacement controls the allowed original amount",
                blocking=False, ordinary_allowed_original=_text(ordinary_allowed),
                replacement_allowed_original=_text(replacement))
    result["allowed_original"] = _text(allowed)

    if currency == "EUR":
        rate = Decimal(1)
    else:
        candidates = [row for row in fx_rows if row.get("Currency") == currency]
        matching = []
        for row in candidates:
            try:
                rate_day = _day(row.get("Rate date"))
            except ValueError as error:
                refs([row])
                finding("invalid_rate", str(error))
                return result
            if rate_day == paid_on:
                matching.append(row)
        refs(matching)
        if len(matching) != 1:
            refs(candidates, "REGISTERS-FX:complete-tab")
            finding("missing_rate" if not matching else "ambiguous_rate",
                    "Need exactly one exact payment-date rate for the expense currency")
            return result
        try:
            rate = _decimal(matching[0].get("EUR per currency unit"))
            if rate <= 0:
                raise ValueError("Exchange rate must be positive")
        except ValueError as error:
            finding("invalid_rate", str(error))
            return result
    with localcontext() as context:
        context.prec = _precision(allowed, rate)
        converted = (allowed * rate).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result["allowed_cents"] = int(converted * 100)
    result["rate"] = _text(rate)
    return result
"""Build local fact-specific repair work from verified batch observations.

This module sends nothing and invents no replies. Its response records describe
source-bound verification, not conversations caused by generated drafts. Resolving
a factual queue item grants no approval, partial payment or financial closure.
"""

from collections import defaultdict
from datetime import date
from hashlib import sha256
import json

from .authority import ROLE_FIELDS, _refs
from .independence import visible_at


def _key(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _hash(value):
    return sha256(_key(value).encode("utf-8")).hexdigest()[:24]


def _sources(*groups):
    return sorted({value for group in groups for value in (group or []) if isinstance(value, str) and value})


def _line_sources(observation):
    return _sources([observation.get("source_ref")], *[
        _sources(line.get("source_refs"), line.get("calculation", {}).get("source_refs"))
        for line in observation.get("lines", [])])


def _financial_sources(observation):
    return _sources([observation.get("source_ref")], *[
        request.get("source_refs", []) for request in observation.get("original_requests", {}).values()])


def _return_route(row, person):
    """Route established repair tasks independently of who returned the review.

    Interview lines 151/159/175 assign missing claim evidence to the employee,
    and line 167 assigns funding decisions to the budget owner. These are task
    routes, never subject-ID or returning-role special cases. An unfamiliar
    request needs administrative routing rather than an inferred provider.
    """
    task = " ".join(str(row.get("Repair requested", "")).casefold().split()).rstrip(".")
    if task == "provide revised trip evidence" and person.get("Employee ID"):
        return (person["Employee ID"], "employee", row["Repair requested"],
                "Employee supplies missing claim evidence (interview lines 151/159/175)")
    if task == "obtain funding decision" and person.get("Budget owner"):
        return (person["Budget owner"], "budget_owner", row["Repair requested"],
                "Directory budget owner controls funding decisions (interview line 167)")
    return (person.get("Administration reviewer") or "Unassigned administration", "administration_escalation",
            "Establish the responsible provider for the returned task, then obtain its source-bound repair",
            "Unrecognized task responsibility requires administrative escalation (interview lines 159/175)")


def _proof(item, observation, review_rows, processes):
    """A missing issue alone is insufficient; require the relevant positive fact."""
    if observation.get("revision") != item["revision"]:
        return None
    code, cost_id = item["code"], item.get("cost_id")
    lines = [line for line in observation.get("lines", []) if cost_id is None or line.get("cost_id") == cost_id]
    line_codes = {"paid_evidence", "missing_rate", "ambiguous_rate", "invalid_rate", "missing_cap",
                  "ambiguous_cap", "invalid_cap", "unknown_category", "invalid_input", "late_filing"}
    if code in line_codes and cost_id is None and len(lines) > 1:
        proved = all(line.get("evidence_supported") is True for line in lines)
        if code != "paid_evidence":
            proved = proved and all(line.get("calculation", {}).get("allowed_cents") is not None for line in lines)
        return _line_sources(observation) if proved else None
    if code in {"approval_reply", "review_return"}:
        valid = set(observation.get("authority", {}).get("valid_decision_ids", []))
        missing = set(observation.get("authority", {}).get("missing_roles", []))
        approved = set()
        refs = []
        for row in review_rows:
            if (row.get("Decision reference") in valid and row.get("Subject type") == "claim"
                    and row.get("Subject reference") == item["subject_id"]
                    and row.get("Revision") == item["revision"] and row.get("Outcome") == "approve"):
                approved.update(set(_refs(row.get("Review roles"))) - missing)
                refs.extend([row.get("_ref")])
        if set(item.get("roles", [])) <= approved:
            return _sources([observation.get("source_ref")], refs)
        return None
    if code == "approval_requirement":
        if (observation.get("calculated_entitlement_cents") is not None
                and "director_requirement_unknown" not in observation.get("authority", {}).get("missing_roles", [])):
            return _line_sources(observation)
        return None
    for line in lines:
        calculation = line.get("calculation", {})
        blocking = {finding.get("code") for finding in calculation.get("findings", []) if finding.get("blocking", True)}
        proved = False
        if code == "paid_evidence":
            proved = line.get("evidence_supported") is True
        elif code in {"missing_rate", "ambiguous_rate", "invalid_rate"}:
            proved = calculation.get("rate") is not None and not blocking & {"missing_rate", "ambiguous_rate", "invalid_rate"}
        elif code in {"missing_cap", "ambiguous_cap", "invalid_cap", "unknown_category", "invalid_input"}:
            proved = calculation.get("allowed_original") is not None and code not in blocking
        elif code == "late_filing":
            try:
                proved = (line.get("evidence_supported") is True
                          and date.fromisoformat(line["first_filed"]) <= date.fromisoformat(line["filing_deadline"])
                          and "eligibility" in observation.get("full_recheck_steps", []))
            except (KeyError, ValueError, TypeError):
                proved = False
        if proved:
            return _sources([observation.get("source_ref")], line.get("source_refs"), calculation.get("source_refs"))
    if code in line_codes:
        return None
    if code == "finance_resolution" and observation.get("current_resolution_event_ids"):
        return _financial_sources(observation)
    if code == "overpayment" and observation.get("calculated_balance_cents") is not None and observation["calculated_balance_cents"] >= 0:
        return _financial_sources(observation)
    if (code == "obligation_mismatch" and observation.get("calculated_entitlement_cents") is not None
            and observation.get("finance", {}).get("current_obligation_cents") == observation["calculated_entitlement_cents"]):
        return _financial_sources(observation)
    if code == "shared_budget" and observation.get("budget", {}).get("sufficient") is True:
        return _sources(observation["budget"].get("source_refs"), *[
            charge.get("source_refs", []) for charge in observation["budget"].get("charges", [])])
    if (code == "shared_cost_obligation" and observation.get("shared_cost_request_ids") == []
            and "budget and obligations" in observation.get("full_recheck_steps", [])):
        return _financial_sources(observation)
    if code == "cancellation_pending":
        for process in processes:
            if (process.get("status") == "confirmed" and process.get("confirmed_time")
                    and process.get("trip") == item.get("trip_id")
                    and process.get("trip_revision") == item.get("trip_revision")
                    and item.get("cancellation_id") == process.get("cancellation_id")):
                return process["source_refs"]
        return None
    if code in {"finance_resolution", "overpayment", "obligation_mismatch", "shared_budget", "shared_cost_obligation"}:
        return None
    if observation.get("current_recheck_supported") is True and observation.get("full_recheck_steps"):
        return _sources(_line_sources(observation), _financial_sources(observation),
                        observation.get("authority", {}).get("source_refs"))
    return None


def build_queue(run_id, batches, versions, reviews, people):
    """Return ``items``, status-separated ``owner_views`` and run/batch ``changes``.

    ``batches`` is the ordered cumulative recheck output. Line-specific issues
    should carry ``cost_id`` and may carry ``requested_facts``. Current approval
    gaps expand into exact directory roles; admitted returns retain their own
    reason, affected fields and reviewer, separately from the repair provider.
    A new claim revision supersedes old
    work, never resolves it using a reply for another version.

"""Offline source-bound verification of the adopted independence constraint.

This component observes initial-batch evidence, authorizations and commitments.
It does not calculate final entitlement, dispatch requests, close claims, choose
correction scope, or organize the operational repair queue.
"""

import argparse
from datetime import datetime, time, timedelta
from decimal import Decimal
from hashlib import sha256
import json
from pathlib import Path
import re
from zoneinfo import ZoneInfo

from .independence import Check, Work, budget_remaining, cents, evaluate, visible_at


class SourceError(ValueError):
    pass


class Sources:
    def __init__(self, manifest):
        self.path = Path(manifest).resolve()
        self.base = self.path.parent
        self.data = json.loads(self.path.read_text(encoding="utf-8"))
        entries = self.data["files"]
        self.files = {e["source_id"]: e for e in entries}
        if len(self.files) != len(entries) or len({e["url"] for e in entries}) != 5:
            raise SourceError("Need unique source IDs and coverage of all five native URLs")
        for entry in entries:
            if entry["status"] != "read":
                raise SourceError("This verification requires complete retained sources")
            path = (self.base / entry["path"]).resolve()
            if not path.is_relative_to(self.base) or sha256(path.read_bytes()).hexdigest() != entry["sha256"]:
                raise SourceError("Missing, unsafe or hash-mismatched retained source: " + entry["source_id"])

    def read(self, source_id):
        entry = self.files[source_id]
        return json.loads((self.base / entry["path"]).read_text(encoding="utf-8"), parse_float=Decimal)

    def table(self, name):
        source_id = "REGISTERS-" + name.upper().replace(" ", "-")
        sheet = self.read(source_id)["sheets"][0]
        rows = sheet["data"][0]["rowData"]
        headers = [v["formattedValue"] for v in rows[4]["values"]]
        result = []
        for index, data in enumerate(rows[5:], 6):
            values = data.get("values", [])
            row = {}
            for column, header in enumerate(headers):
                cell = values[column] if column < len(values) else {}
                value = cell.get("effectiveValue", {})
                if "date" in header.lower() or "time" in header.lower():
                    row[header] = cell.get("formattedValue")
                else:
                    row[header] = next(iter(value.values()), None)
            if any(v is not None for v in row.values()):
                row["_ref"] = f"{source_id}:row{index}"
                result.append(row)
        return result


def field(text, label):
    match = re.search(r"^\s*" + re.escape(label) + r":\s*([^\n]+)", text, re.M)
    if not match:
        raise SourceError("Missing binder field: " + label)
    return match.group(1).strip()


def initial_claims(sources):
    claims = {}
    for page in sources.read("INITIAL-PAGES"):
        text = page["text"]
        lines = [dict(cost_id=m[0], receipt_id=m[1], first_submitted=m[2], gross=Decimal(m[3]), currency=m[4]) for m in re.findall(r"^\s*\d+\s+(\S+)\s+(\S+)\s+(\d{4}-\d{2}-\d{2})\s+(\d+\.\d+)\s+([A-Z]{3})\s*$", text, re.M)]
        if not lines:
            raise SourceError("No expense lines in initial claim page")
        item = dict(id=field(text, "Claim reference"), revision=int(field(text, "Revision")), batch=int(field(text, "Arrival batch")), employee=field(text, "Employee"), trip=field(text, "Trip reference"), trip_revision=int(field(text, "Trip revision")), lines=lines, source_ref=f"INITIAL:page{page['page']}")
        if item["id"] in claims:
            raise SourceError("Ambiguous initial claim identity")
        claims[item["id"]] = item
    return claims


def receipt_records(sources):
    receipts = {}
    for page in sources.read("RECEIPTS-PAGES"):
        for block in re.split(r"(?=Receipt reference:)", page["text"])[1:]:
            key = field(block, "Receipt reference")
            if key in receipts:
                raise SourceError("Duplicate receipt identity")
            employee_label = "Employee ID" if re.search(r"^\s*Employee ID:", block, re.M) else "Employee"
            receipts[key] = dict(cost_id=field(block, "Expense reference"), employee=field(block, employee_label), trip=field(block, "Trip reference"), currency=field(block, "Currency"), gross=Decimal(field(block, "Gross amount")), source_ref=f"RECEIPTS:page{page['page']}")
    return receipts


def split(value):
    return tuple(str(value).splitlines()) if value else ()


def single(rows, label):
    if len(rows) != 1:
        raise SourceError("Missing or ambiguous " + label)
    return rows[0]


def before_clock(value, sources):
    if not value:
        return False
    event = datetime.strptime(value, "%Y-%m-%d %H:%M:%S UTC").replace(tzinfo=ZoneInfo("UTC"))
    day = datetime.strptime(sources.data["case_clock"], "%Y-%m-%d").date()
    end = datetime.combine(day + timedelta(days=1), time(), ZoneInfo(sources.data["case_timezone"]))
    return event < end


def payment_check(claim, line, receipt, payments, case_clock):
    """A matching cost ID alone is insufficient; all evidence identities must bind."""
    expected = (line["cost_id"], claim["employee"], claim["trip"], line["currency"], line["gross"])
    receipt_matches = receipt is not None and tuple(receipt[k] for k in ("cost_id", "employee", "trip", "currency", "gross")) == expected
    matching = [r for r in payments if (r["Expense reference"], r["Employee ID"], r["Trip reference"], r["Currency"], r["Gross amount"]) == expected and r["Receipt reference"] == line["receipt_id"] and r["Payment status"] == "settled" and r["Paid date"] and datetime.strptime(r["Paid date"], "%Y-%m-%d").date() <= datetime.strptime(case_clock, "%Y-%m-%d").date()]
    ok = receipt_matches and len(matching) == 1
    refs = (claim["source_ref"], receipt["source_ref"] if receipt else "RECEIPTS:all-pages", *(r["_ref"] for r in matching))
    if not matching:
        refs += ("REGISTERS-MERCHANT-PAYMENTS:complete-tab",)
    action = f"Supply matching settled merchant proof for {line['receipt_id']}; retain the existing matched receipt" if receipt_matches else f"Supply original receipt and separate settled proof bound to employee, trip, cost, currency, gross and {line['receipt_id']}"
    return Check("evidence", ok, f"{claim['id']} revision {claim['revision']} / {line['cost_id']}: receipt and matching settled merchant proof " + ("verified" if ok else "missing, ambiguous or incompatible"), claim["employee"], action, refs)


